import { test } from 'vitest';
import {
  DEFAULT_SIZE,
  PREFERENCES_KEY,
  PREFERENCES_VERSION,
  readPreferences,
  rememberBest,
  writePreferences,
} from './storage.ts';
import { MOVES_MAX } from '../game.ts';
import { SPEC_VECTOR } from '../game.fixture.ts';
import type { PreferenceStore } from './storage.ts';

function memoryStore(initial = ''): PreferenceStore {
  const entries = new Map([[PREFERENCES_KEY, initial]]);
  return {
    getItem: (key) => entries.get(key) ?? null,
    setItem: (key, value) => {
      entries.set(key, value);
    },
  };
}

test('preferences round trip size and separate minimum moves per size', () => {
  const store = memoryStore();
  const preferences = rememberBest(rememberBest({ size: 6, bestMoves: {} }, 4, 12), 6, 20);
  writePreferences(store, preferences);
  assert.deepEqual(readPreferences(store), preferences, 'R10 scores survive storage round trip');
  assert.equal(rememberBest(preferences, 4, 13), preferences, 'R10 worse score keeps best');
  assert.equal(rememberBest(preferences, 4, 12), preferences);
  assert.equal(rememberBest(preferences, 4, 9).bestMoves['4'], 9, 'R10 better score replaces best');
  assert.equal(preferences.bestMoves['6'], 20, 'R10 size six has its separate best');
});

test('a best at the move cap round trips and a larger saved best is ignored', () => {
  const store = memoryStore();
  const capped = { size: DEFAULT_SIZE, bestMoves: { [DEFAULT_SIZE]: MOVES_MAX } };
  writePreferences(store, capped);
  assert.deepEqual(readPreferences(store), capped);
  assert.equal(rememberBest(capped, DEFAULT_SIZE, MOVES_MAX), capped);
  const larger = {
    schemaVersion: PREFERENCES_VERSION,
    size: DEFAULT_SIZE,
    bestMoves: { [DEFAULT_SIZE]: MOVES_MAX + 1 },
  };
  store.setItem(PREFERENCES_KEY, JSON.stringify(larger));
  assert.deepEqual(readPreferences(store), { size: DEFAULT_SIZE, bestMoves: {} });
});

const INVALID_PREFERENCES = [
  '{',
  'null',
  '{}',
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 5, bestMoves: {} }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: 1 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: -1 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: 8.5 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { '04': 8 } }),
];
for (const [index, text] of INVALID_PREFERENCES.entries()) {
  test(`preferences ignore invalid saved data ${index + 1}`, () => {
    assert.deepEqual(readPreferences(memoryStore(text)), { size: DEFAULT_SIZE, bestMoves: {} });
  });
}

test('storage failures keep play available and never change unrelated keys', () => {
  const denied: PreferenceStore = {
    getItem: () => {
      throw new Error();
    },
    setItem: () => {
      throw new Error();
    },
  };
  assert.equal(DEFAULT_SIZE, SPEC_VECTOR.sizes[0]);
  assert.equal(readPreferences(denied).size, DEFAULT_SIZE);
  assert.doesNotThrow(() => writePreferences(denied, { size: DEFAULT_SIZE, bestMoves: {} }));
  assert.equal(readPreferences(null).size, DEFAULT_SIZE);
  const store = memoryStore();
  const unrelated = 'another-application';
  store.setItem(unrelated, 'kept');
  writePreferences(store, { size: DEFAULT_SIZE, bestMoves: {} });
  assert.equal(store.getItem(unrelated), 'kept');
});
import assert from 'node:assert/strict';
import { test } from 'vitest';
import { sourceFiles } from './source-files.ts';

const EXPORT = /^export (?:async )?(const|function|interface|type|class) (\w+)/gm;
const NAMED_IMPORT = /^import\s+(?:type\s+)?\{([^}]*)\} from/gm;
const CHECK = /^export function (\w+)\([^)]*\): (?:boolean|\w+ is )/gm;
const TEST_NAME = /\btest\(\s*(['`])(.*?)\1/gs;
const REQUIREMENT_ID = /\b[A-Z]\d{2}\b/;
const ENVIRONMENT = /process\.env(?:\.(\w+)|\[(\w+)\])/g;

async function typescriptFiles() {
  const files = (await Promise.all(['src', 'scripts', 'tests', 'art'].map(sourceFiles))).flat();
  return files.filter((file) => /\.tsx?$/.test(file.path));
}

// Keeps each imported name, without a type marker or local alias.
function importedNames(text: string): string[] {
  return [...text.matchAll(NAMED_IMPORT)].flatMap((match) =>
    (match[1] ?? '').split(',').map((name) => name.replace(/\btype\s+|\s+as\s+\w+/g, '').trim()),
  );
}

test('every export has an importer and each exported value has one owner', async () => {
  const files = await typescriptFiles();
  const imported = new Set(files.flatMap((file) => importedNames(file.text)));
  const owners = new Map<string, string>();
  for (const file of files)
    for (const [, kind, name = ''] of file.text.matchAll(EXPORT)) {
      assert.ok(imported.has(name), `${file.path} exports ${name} that nothing imports`);
      if (kind !== 'const') continue;
      assert.equal(owners.get(name), undefined, `${name} is exported by one owner`);
      owners.set(name, file.path);
    }
});

test('exported yes or no checks are named as questions', async () => {
  for (const file of await typescriptFiles())
    for (const [, name = ''] of file.text.matchAll(CHECK))
      assert.match(name, /^(?:is|has)[A-Z]/, `${file.path} names its check ${name}`);
});

test('test names describe behavior without requirement IDs', async () => {
  const files = await typescriptFiles();
  for (const file of files.filter((file) => /\.test\.ts$/.test(file.path)))
    for (const [, , name = ''] of file.text.matchAll(TEST_NAME))
      assert.doesNotMatch(name, REQUIREMENT_ID, `${file.path} test name ${name}`);
});

test('source reads only the environment its command and test runners need', async () => {
  const reads = (await typescriptFiles()).flatMap((file) =>
    [...file.text.matchAll(ENVIRONMENT)].map((match) => `${file.path}:${match[1] ?? match[2]}`),
  );
  const runners = [
    'scripts/replay-cli.ts:INIT_CWD',
    'scripts/replay.test.ts:npm_execpath',
    'tests/browser-test.ts:EXECUTABLE_ENV',
    'tests/browser-test.ts:NAMED_COMBINATION_ENV',
    'tests/browser-test.ts:NPM_AGENT_ENV',
    'tests/browser-test.ts:TEMP',
    'tests/browser-test.ts:TMP',
  ];
  assert.deepEqual([...new Set(reads.map((read) => read.replaceAll('\\', '/')))].sort(), runners);
});

# Neon Pairs

Neon Pairs is a memory game that runs offline from one HTML file and keeps local best moves for each board size.

You can repeat a deal with its board code, save progress as a snapshot or run timed actions through the replay command.

Status: implements product spec version 2.2.

## Install

Use the named test combination, Node 26.12.1, npm 11.20.0 and Playwright 1.64.1 with Chromium 156.0.8078.4. From this folder, install the locked tools:

```powershell
npm ci --cache .npm-cache
$env:PLAYWRIGHT_BROWSERS_PATH = Join-Path $PWD '.playwright-browsers'
$env:TEMP = Join-Path $PWD '.browser-work'
$env:TMP = $env:TEMP
New-Item -ItemType Directory -Force -Path $env:TEMP | Out-Null
npm exec --cache .npm-cache -- playwright install chromium
```

These settings keep the browser download and temporary files inside the project. Browser tests use fresh contexts. They stop their browser and local HTTP server when they finish.

## Play

Run `npm run build`, then open `dist/index.html` from disk. The game makes no network requests. To keep saved sizes and scores on a stable HTTP origin, run `npm run dev`. Stop it when you finish.

Use Grid size to choose a board. Reveal two cards with a click, tap, Enter or Space. Arrow keys move board focus. Other keys stay with the browser. Tab leaves the board. New Game gives another deal. Restart repeats the current deal.

Open Reproduce a game to load a board code or export progress. Loading an unfinished snapshot pauses it. Resume returns focus to the remembered card and continues the remaining mismatch interval. A completed snapshot loads as completed without Resume. Elapsed time stops at 359999999ms while play continues. The minutes and seconds display reaches 5999:59. Moves stop at 999999. Matching and victory continue at that count. Saved bests use the same move limit.

## Replay

Run `npm run --silent replay -- PATH` with a version 1 replay JSON file. Valid input prints only its final version 1 snapshot JSON to stdout and exits 0. Invalid input prints nothing to stdout, writes a message to stderr and exits nonzero. The command's silent flag suppresses its npm banner so stdout stays JSON. Other npm commands keep their errors and warnings. Replay timestamps can reach the safe integer limit. Elapsed time uses the same cap as browser play.

## Check

Run the checks from this folder:

```powershell
npm run typecheck
npm test
$env:NEON_PAIRS_NAMED_COMBINATION = '1'
npm run test:e2e
npm run format:check
```

`npm test` runs the unit and static checks with Vitest 5.0.5. `test:e2e` type checks and builds current source before opening the new HTML. It also builds the face sheet and session harness as separate diagnostic entries. The game distribution contains no diagnostic entry.

The browser command writes the Node, npm, Playwright and Chromium versions it ran on to `test-results/browser-runtime.json`. With `NEON_PAIRS_NAMED_COMBINATION` set to `1`, it also fails unless they match the named combination. Use the flag for named-combination evidence. Other supported runtimes, such as Node 24.19, run without it.

The locked install, type check, Vitest unit tests, build from current source and Chromium journeys have passed on the named combination with the flag set. Other versions have no test record here.

## Accessibility

Keyboard, card names, atomic turn feedback, reduced motion, touch scrolling and the equivalent zoom layout at 640x400 CSS pixels with device scale 2 have browser checks. The diagnostic face sheet draws all 128 faces at 44px.

